<script setup lang="ts">
import type { EvidenceStatus, ProjectDocument } from '~~/shared/types/project'
const props = defineProps<{ project: ProjectDocument }>()
const labels: Record<EvidenceStatus, string> = { verified: 'Проверено по данным', unverified: 'Не проверено', blocked: 'Не готово', 'not-applicable': 'Не требуется' }
const attention = computed(() => props.project.evidence.items.filter(item => item.status !== 'verified'))
const verified = computed(() => props.project.evidence.items.filter(item => item.status === 'verified'))
</script>
<template>
  <div class="stack">
    <section><h2>Что проверить перед строительством</h2><p class="muted">Расчёт готов, но площадка и работа завода ещё требуют проверки в игре. Личные отметки этапов не снимают эти ограничения.</p><ul><li v-for="blocker in project.readiness.blockers" :key="blocker">{{ constructionText(blocker) }}</li></ul><p v-if="!project.readiness.blockers.length">В плане нет открытых ограничений. Сверь его с текущим миром перед строительством.</p></section>
    <section><h2>Ещё не подтверждено</h2><div class="evidence-list"><article v-for="item in attention" :key="item.id"><details><summary class="evidence-summary"><span>{{ constructionText(item.label) }}</span><span class="tag" :data-status="item.status">{{ labels[item.status] }}</span></summary><p>{{ constructionText(item.detail) }}</p><p v-if="item.source" class="recipe-path fine">{{ constructionText(item.source) }}</p></details></article></div><p v-if="!attention.length" class="fine">Открытых проверок в этой версии плана нет.</p></section>
    <section><h2>Проверено по исходным данным</h2><p class="fine">Эти проверки подтверждают план, а не фактическую работу станков.</p><div class="evidence-list"><article v-for="item in verified" :key="item.id"><details><summary class="evidence-summary"><span>{{ constructionText(item.label) }}</span><span class="tag" data-status="verified">{{ labels[item.status] }}</span></summary><p>{{ constructionText(item.detail) }}</p><p v-if="item.source" class="recipe-path fine">{{ constructionText(item.source) }}</p></details></article></div><p v-if="!verified.length" class="fine">Подтверждённых проверок в этой версии плана нет.</p></section>
    <details class="reference-disclosure"><summary>Версия проекта и контрольные суммы</summary><dl class="source-facts"><div><dt>Снимок данных</dt><dd>{{ constructionText(project.source.snapshotLabel) }}</dd></div><div><dt>SHA-256 сейва</dt><dd class="recipe-path">{{ project.source.saveSha256 }}</dd></div><div><dt>Ревизия проекта</dt><dd class="recipe-path">{{ project.revision }}</dd></div></dl><p v-for="note in project.evidence.notes" :key="note">{{ constructionText(note) }}</p></details>
    <details v-if="project.evidence.sources.length" class="reference-disclosure"><summary>Источники проекта</summary><ul class="source-links"><li v-for="source in project.evidence.sources" :key="source.url"><a class="text-link" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.label }}<span class="sr-only"> (новая вкладка)</span></a></li></ul></details>
    <details class="reference-disclosure"><summary>Скачать данные и чертежи</summary><ul class="download-list"><li><a class="text-link" :href="`/atlas/${project.saveId}/${project.id}/project.json`" download>Полный проект JSON</a></li><li v-for="download in project.evidence.downloads" :key="download.path"><a class="text-link" :href="download.path" download>{{ download.label }}</a></li></ul><p class="fine">Игровые сохранения и приватные журналы не опубликованы.</p></details>
  </div>
</template>
